"use client";

import { useEffect, useState, useCallback } from "react";
import { useVendorStore } from "@/stores/vendorStore";
import { useAuthStore } from "@/stores/authStore";
import { toast } from "sonner";
import {
  Banknote,
  Loader2,
  ChevronLeft,
  ChevronRight,
  CheckCircle2,
  Clock,
  XCircle,
  Ban,
  CalendarDays,
} from "lucide-react";

const STATUS_TABS = [
  { value: "", label: "All" },
  { value: "PENDING", label: "Pending" },
  { value: "PROCESSING", label: "Processing" },
  { value: "PAID", label: "Paid" },
  { value: "FAILED", label: "Failed" },
];

const STATUS_STYLES: Record<string, { bg: string; text: string; icon: any }> = {
  PENDING: { bg: "bg-amber-50 dark:bg-amber-900/30 dark:bg-amber-900/30", text: "text-amber-800 dark:text-amber-300", icon: Clock },
  PROCESSING: { bg: "bg-blue-50 dark:bg-blue-900/30 dark:bg-blue-900/30", text: "text-blue-800 dark:text-blue-300", icon: Clock },
  PAID: { bg: "bg-emerald-50 dark:bg-emerald-900/30 dark:bg-emerald-900/30", text: "text-emerald-800 dark:text-emerald-300", icon: CheckCircle2 },
  FAILED: { bg: "bg-red-50 dark:bg-red-900/30 dark:bg-red-900/30", text: "text-red-800", icon: XCircle },
};

function formatCurrency(amount: number) {
  return `₹${amount.toLocaleString("en-IN", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
}

function formatDate(dateStr: string) {
  return new Date(dateStr).toLocaleDateString("en-IN", { day: "numeric", month: "short", year: "numeric" });
}

export default function SettlementsPage() {
  const { user } = useAuthStore();
  const { settlements, settlementsTotal, settlementsPage, settlementsTotalPages, isSettlementsLoading, fetchSettlements } = useVendorStore();
  const [statusFilter, setStatusFilter] = useState("");
  const [page, setPage] = useState(1);

  const vendorId = user?.vendorProfile?.id;

  useEffect(() => {
    if (vendorId) {
      fetchSettlements(vendorId, page, 20, statusFilter || undefined).catch(() => toast.error("Failed to load settlements"));
    }
  }, [vendorId, page, statusFilter, fetchSettlements]);

  if (!vendorId) {
    return (
      <div className="mx-auto max-w-4xl">
        <h1 className="text-2xl font-bold text-gray-900 dark:text-gray-100 dark:text-gray-100 mb-2">Settlements</h1>
        <p className="text-sm text-gray-500 dark:text-gray-400 dark:text-gray-500 dark:text-gray-400 dark:text-gray-500 dark:text-gray-500 dark:text-gray-400 dark:text-gray-500">Vendor profile not found</p>
      </div>
    );
  }

  return (
    <div className="mx-auto max-w-4xl">
      <div className="mb-6">
        <h1 className="text-2xl font-bold text-gray-900 dark:text-gray-100 dark:text-gray-100">Settlements</h1>
        <p className="mt-0.5 text-sm text-gray-500 dark:text-gray-400 dark:text-gray-500 dark:text-gray-400 dark:text-gray-500 dark:text-gray-500 dark:text-gray-400 dark:text-gray-500">Payout history and settlement details</p>
      </div>

      <div className="mb-6 flex gap-2 overflow-x-auto pb-2">
        {STATUS_TABS.map(tab => (
          <button key={tab.value} onClick={() => { setStatusFilter(tab.value); setPage(1); }}
            className={`shrink-0 rounded-full px-4 py-1.5 text-xs font-semibold transition-all ${
              statusFilter === tab.value ? "bg-emerald-700 text-white shadow-sm dark:shadow-gray-950/30" : "bg-white dark:bg-gray-800 dark:bg-gray-800 text-gray-600 dark:text-gray-300 dark:text-gray-300 border border-gray-200 dark:border-gray-700 dark:border-gray-700"
            }`}>{tab.label}</button>
        ))}
      </div>

      {isSettlementsLoading ? (
        <div className="flex items-center justify-center py-20"><Loader2 size={24} className="animate-spin text-emerald-700 dark:text-emerald-400" /></div>
      ) : settlements.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-16">
          <div className="flex h-20 w-20 items-center justify-center rounded-2xl bg-emerald-50 dark:bg-emerald-900/30 dark:bg-emerald-900/30"><Banknote size={36} className="text-emerald-300" /></div>
          <h3 className="mt-6 text-lg font-semibold text-gray-900 dark:text-gray-100 dark:text-gray-100">No settlements yet</h3>
          <p className="mt-1 text-sm text-gray-500 dark:text-gray-400 dark:text-gray-500 dark:text-gray-400 dark:text-gray-500 dark:text-gray-500 dark:text-gray-400 dark:text-gray-500">Settlements will appear once generated by admin</p>
        </div>
      ) : (
        <>
          <p className="mb-4 text-sm text-gray-500 dark:text-gray-400 dark:text-gray-500 dark:text-gray-400 dark:text-gray-500 dark:text-gray-500 dark:text-gray-400 dark:text-gray-500">{settlementsTotal} settlement{settlementsTotal !== 1 ? "s" : ""}</p>
          <div className="space-y-3">
            {settlements.map(s => {
              const style = STATUS_STYLES[s.status] ?? { bg: "bg-gray-50 dark:bg-gray-700/50 dark:bg-gray-700/50", text: "text-gray-700 dark:text-gray-200 dark:text-gray-200", icon: Ban };
              const Icon = style.icon;
              return (
                <div key={s.id} className="rounded-xl border border-gray-200 dark:border-gray-700 dark:border-gray-700 bg-white dark:bg-gray-800 dark:bg-gray-800 p-5 shadow-sm dark:shadow-gray-950/30 transition-all hover:shadow-md dark:shadow-gray-950/30">
                  <div className="flex items-start justify-between">
                    <div>
                      <div className="flex items-center gap-2">
                        <h3 className="text-base font-bold text-gray-900 dark:text-gray-100 dark:text-gray-100">{formatCurrency(s.payableAmount)}</h3>
                        <span className={`inline-flex items-center gap-1 rounded-full px-2.5 py-0.5 text-[11px] font-semibold ${style.bg} ${style.text}`}>
                          <Icon size={11} />{s.status.charAt(0) + s.status.slice(1).toLowerCase()}
                        </span>
                      </div>
                      <div className="mt-2 flex items-center gap-3 text-xs text-gray-500 dark:text-gray-400 dark:text-gray-500 dark:text-gray-400 dark:text-gray-500 dark:text-gray-500 dark:text-gray-400 dark:text-gray-500">
                        <span className="flex items-center gap-1"><CalendarDays size={11} />{formatDate(s.periodStart)} - {formatDate(s.periodEnd)}</span>
                      </div>
                      <div className="mt-3 flex flex-wrap gap-3 text-xs">
                        <span className="text-gray-500 dark:text-gray-400 dark:text-gray-500 dark:text-gray-400 dark:text-gray-500 dark:text-gray-500 dark:text-gray-400 dark:text-gray-500">Sales: <strong className="text-gray-700 dark:text-gray-200 dark:text-gray-200">{formatCurrency(s.totalSales)}</strong></span>
                        <span className="text-gray-500 dark:text-gray-400 dark:text-gray-500 dark:text-gray-400 dark:text-gray-500 dark:text-gray-500 dark:text-gray-400 dark:text-gray-500">Commission: <strong className="text-amber-700 dark:text-amber-400">{formatCurrency(s.commissionAmount)}</strong></span>
                        <span className="text-gray-500 dark:text-gray-400 dark:text-gray-500 dark:text-gray-400 dark:text-gray-500 dark:text-gray-500 dark:text-gray-400 dark:text-gray-500">TDS: <strong className="text-red-700 dark:text-red-400">{formatCurrency(s.tdsDeducted)}</strong></span>
                      </div>
                    </div>
                    <div className="shrink-0 text-right">
                      {s.paidAt && <p className="text-xs text-gray-400 dark:text-gray-500 dark:text-gray-500 dark:text-gray-400 dark:text-gray-500">Paid: {formatDate(s.paidAt)}</p>}
                      {s.utrNumber && <p className="text-[10px] text-gray-400 dark:text-gray-500 dark:text-gray-500 dark:text-gray-400 dark:text-gray-500 mt-1">UTR: {s.utrNumber}</p>}
                    </div>
                  </div>
                </div>
              );
            })}
          </div>

          {settlementsTotalPages > 1 && (
            <div className="mt-6 flex items-center justify-center gap-2">
              <button onClick={() => setPage(p => Math.max(1, p-1))} disabled={page <= 1}
                className="rounded-lg border border-gray-300 dark:border-gray-600 dark:border-gray-600 p-2 text-gray-600 dark:text-gray-300 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700/50 dark:hover:bg-gray-700/50 dark:bg-gray-700/50 disabled:opacity-40"><ChevronLeft size={16} /></button>
              <span className="text-sm text-gray-500 dark:text-gray-400 dark:text-gray-500 dark:text-gray-400 dark:text-gray-500 dark:text-gray-500 dark:text-gray-400 dark:text-gray-500">Page {page} of {settlementsTotalPages}</span>
              <button onClick={() => setPage(p => Math.min(settlementsTotalPages, p+1))} disabled={page >= settlementsTotalPages}
                className="rounded-lg border border-gray-300 dark:border-gray-600 dark:border-gray-600 p-2 text-gray-600 dark:text-gray-300 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700/50 dark:hover:bg-gray-700/50 dark:bg-gray-700/50 disabled:opacity-40"><ChevronRight size={16} /></button>
            </div>
          )}
        </>
      )}
    </div>
  );
}
